import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.net.MalformedURLException;
import java.net.URL;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection.KeyVal kv;

    @Mock
    private URL inputUrl;

    @Test
    public void constructor_MissingUrl_ThrowsMalformedURLException() {
        assertThrows(MalformedURLException.class, () -> new UrlBuilder(null));
    }

    @Test
    public void build_ReturnsUrl_WithInputUrl() throws MalformedURLException {
        when(inputUrl.toString()).thenReturn("http://example.com");
        URL url = new UrlBuilder(inputUrl).build();
        assertEquals("http://example.com", url.toString());
    }

    @Test
    public void appendKeyVal_AppendsKeyValue_WithValidData() throws UnsupportedEncodingException {
        String encodedValue = Base64.getEncoder().encodeToString(new byte[]{(byte) 0x61, (byte) 0x62});
        Map<String, String> keyVals = new HashMap<>();
        keyVals.put("key", "value");
        when(kv.getKey()).thenReturn("key");
        when(kv.getValue()).thenReturn(encodedValue);
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.appendKeyVal(keyVals);
        assertEquals("http://example.com?key=value", urlBuilder.build().toString());
    }

    @Test
    public void appendKeyVal_AppendsKeyValue_WithInvalidData() {
        assertThrows(UnsupportedEncodingException.class, () -> new UrlBuilder(inputUrl).appendKeyVal(kv));
    }
}
